    'Tâche programmée. Première exécution : {date}.' => 'Task scheduled. First run: {date}.',
    'Tâche préparée par MIA : ajustez-la, puis programmez-la. La carte de la conversation sera close.' => 'Task prepared by MIA: adjust it, then schedule it. The card in the conversation will be closed.',
    'Tâche supprimée. Ses conversations restent dans votre historique.' => 'Task deleted. Its conversations remain in your history.',
    'Tâches' => 'Tasks',
    'Tâches & workflows' => 'Tasks & workflows',
    'Tâches Google' => 'Google Tasks',
    'Tâches Microsoft To Do' => 'Microsoft To Do tasks',
    'Tâches programmées' => 'Scheduled tasks',
    'Tâches programmées —' => 'Scheduled tasks —',
    'Télécharger' => 'Download',
    'Télécharger l\'image' => 'Download image',
    'Télécharger l\'image sur l\'ordinateur' => 'Download the image to your computer',
    'Télécharger la sauvegarde' => 'Download the backup',
    'Télécharger la vidéo' => 'Download the video',
    'Télécharger le fichier HTML' => 'Download the HTML file',
    'Télécharger les entrées filtrées (.txt)' => 'Download the filtered entries (.txt)',
    'Télécharger un document d\'essai' => 'Download a sample document',
    'Télécharger une présentation d\'essai' => 'Download a sample presentation',
